# This is intentionally captured exactly once while the module is imported.
# A long-running worker therefore cannot mistake newer bytes on disk for the
# bytecode it actually loaded.
LOADED_CORE_SHA256 = hashlib.sha256(Path(__file__).read_bytes()).hexdigest()

# Codex 0.147.0-alpha.1.2 does not expose a signed/versioned runtime identity
# attestation before a request is routed.  A requested model/effort flag is not
# proof of the serving runtime, so canary and production routing remain closed
# until an officially supported attestation handshake is implemented here.
CODEX_RUNTIME_ATTESTATION_SUPPORTED = False
CODEX_RUNTIME_ATTESTATION_SCHEMA = "codex-runtime-identity-attestation-v1"

_PROCESS_RESOURCE_ERRNOS = frozenset(
    {errno.EAGAIN, errno.ENOMEM, errno.EMFILE, errno.ENFILE}
)


def process_resource_error_code(exc: OSError) -> str | None:
    """Preserve process-creation resource exhaustion across child boundaries."""

    if exc.errno not in _PROCESS_RESOURCE_ERRNOS:
        return None
    name = errno.errorcode.get(exc.errno, f"ERRNO_{exc.errno}").lower()
    return f"process_resource_{name}"


def release_identity(config: Mapping[str, Any]) -> tuple[str, str]:
    """Return the deployed release identity or a truthful source-only fallback."""

    release = config.get("release")
    if not isinstance(release, Mapping):
        return LOADED_CORE_SHA256, "loaded_core_only"
    manifest_value = release.get("manifest_path")
    if not isinstance(manifest_value, str) or not Path(manifest_value).is_absolute():
        raise PreprocessorError("config_release_manifest_path_invalid")
    manifest_path = Path(manifest_value).resolve()
    if not manifest_path.is_file() or manifest_path.stat().st_size > 1024 * 1024:
        raise PreprocessorError("release_manifest_missing")
    manifest = load_json(manifest_path)
    release_id = manifest.get("release_id")
    if (
        manifest.get("schema_version") != RELEASE_SCHEMA
        or not isinstance(release_id, str)
        or SHA256_RE.fullmatch(release_id) is None
    ):
        raise PreprocessorError("release_manifest_invalid")
    return release_id, "release_manifest"

