FORBIDDEN_BUNDLE_KEYS = {
    "history",
    "historical_questions",
    "related",
    "related_questions",
    "recommendation",
    "recommendations",
    "variant",
    "variants",
    "formal_library",
    "formal_nodes",
    "other_question",
    "other_questions",
    "previous_question",
    "previous_questions",
    "path",
    "file_path",
    "absolute_path",
    "locator",
}

# English candidate documents are intended for answer-safe delayed curation.
# These keys are never needed in that artifact and are rejected recursively so
# a model cannot hide protected answer material in a nested card or grounding
# object.  ``answer_protection`` remains valid in immutable input events; this
# guard applies only to model output and staged candidate documents.
ENGLISH_CANDIDATE_FORBIDDEN_ANSWER_KEYS = {
    "answer",
    "answer_key",
    "correct_answer",
    "correct_option",
    "correct_options",
    "full_answer",
    "standard_answer",
    "standard_explanation",
}

# The analysis stage is finalized before the independent critic runs, so the
# checkpoint contains both model-owned item semantics and deterministic
# host-owned bindings.  The critic's output schema only owns the fields below.
# Never ask it to delete or correct sentence/evidence/identity bindings that
# the host will deterministically recompute after review.
ENGLISH_REVIEW_SEMANTIC_ITEM_KEYS = {
    "item_id",
    "sequence",
    "item",
    "candidate_type",
    "candidate_status",
    "tier",
    "source_event_id",
    "bank_status",
    "bank_match_ids",
    "mastered_status",
    "mastery_proposal",
    "grounding",
    "card",
}

ENGLISH_CORRECTION_PATH_ABSENT = {
    "host_path_state": "absent",
}


def english_review_semantic_draft(draft: Mapping[str, Any]) -> dict[str, Any]:
    """Project a finalized English draft onto the critic-owned namespace."""

    rows = draft.get("items")
    if not isinstance(rows, list):
        raise PreprocessorError("english_review_semantic_draft_invalid")
    projected: list[dict[str, Any]] = []
    for row in rows:
        if (
            not isinstance(row, Mapping)
            or not ENGLISH_REVIEW_SEMANTIC_ITEM_KEYS.issubset(row)
        ):
            raise PreprocessorError("english_review_semantic_draft_invalid")
        projected.append(
            {
                key: copy.deepcopy(row[key])
                for key in ENGLISH_REVIEW_SEMANTIC_ITEM_KEYS
            }
        )
    return {"items": projected}


def validate_english_candidate_answer_safety(value: Any) -> None:
    pending: list[Any] = [value]
    while pending:
        current = pending.pop()
        if isinstance(current, Mapping):
            for raw_key, nested in current.items():
                key = str(raw_key).strip().casefold()
                if key in ENGLISH_CANDIDATE_FORBIDDEN_ANSWER_KEYS:
                    raise PreprocessorError("english_candidate_answer_leak")
                pending.append(nested)
        elif isinstance(current, list):
            pending.extend(current)


def validate_english_mcp_grounding(
    items: Any, *, grounding_manifest: Mapping[str, Any]
) -> None:
    """Require artifact and library grounding from this exact English stage."""

    if not isinstance(items, list) or not items:
        raise PreprocessorError("english_mcp_grounding_missing")

    if not isinstance(grounding_manifest, Mapping):
        raise PreprocessorError("english_mcp_grounding_missing")
    manifest_items = grounding_manifest.get("items")
    if not isinstance(manifest_items, list) or not manifest_items:
        raise PreprocessorError("english_mcp_grounding_missing")
    if (
        grounding_manifest.get("schema_version")
        != "model_mcp_grounding_manifest_v1"
        or grounding_manifest.get("item_count") != len(manifest_items)
        or grounding_manifest.get("host_semantic_prefetch") is not False
        or grounding_manifest.get("formal_write_count") != 0
    ):
        raise PreprocessorError("english_mcp_grounding_invalid")
    manifest_sha256 = grounding_manifest.get("manifest_sha256")
    manifest_core = {
        key: copy.deepcopy(value)
        for key, value in grounding_manifest.items()
        if key != "manifest_sha256"
    }
    if (
        not isinstance(manifest_sha256, str)
        or manifest_sha256 != sha256_value(manifest_core)
    ):
        raise PreprocessorError("english_mcp_grounding_invalid")

    rows_by_ref: dict[str, Mapping[str, Any]] = {}
    transcript_sha256s: set[str] = set()
    for row in manifest_items:
        if not isinstance(row, Mapping):
            raise PreprocessorError("english_mcp_grounding_invalid")
        evidence_ref = row.get("evidence_ref")
        consumed_in = row.get("consumed_in")
        if (
            not isinstance(evidence_ref, str)
            or not evidence_ref.startswith("mcp-item:english:")
            or MCP_ITEM_REF_RE.fullmatch(evidence_ref) is None
            or evidence_ref in rows_by_ref
            or row.get("subject") != "english"
            or not isinstance(row.get("collection"), str)
            or not row.get("collection")
            or not isinstance(consumed_in, list)
            or not consumed_in
        ):
            raise PreprocessorError("english_mcp_grounding_invalid")
        for binding in consumed_in:
            transcript_sha256 = (
                binding.get("transcript_sha256")
                if isinstance(binding, Mapping)
                else None
            )
            if (
                not isinstance(transcript_sha256, str)
                or SHA256_RE.fullmatch(transcript_sha256) is None
            ):
                raise PreprocessorError("english_mcp_grounding_invalid")
            transcript_sha256s.add(transcript_sha256)
        rows_by_ref[evidence_ref] = row
    if len(transcript_sha256s) != 1:
        raise PreprocessorError("english_mcp_grounding_invalid")

    for item in items:
        grounding = item.get("grounding") if isinstance(item, Mapping) else None
        refs = (
            grounding.get("mcp_evidence_refs")
            if isinstance(grounding, Mapping)
            else None
        )
        if refs is None or refs == []:
            raise PreprocessorError("english_mcp_grounding_missing")
        if not isinstance(refs, list):
            raise PreprocessorError("english_mcp_grounding_invalid")
        if any(
            not isinstance(ref, str)
            or not ref.startswith("mcp-item:english:")
            or MCP_ITEM_REF_RE.fullmatch(ref) is None
            or ref not in rows_by_ref
            for ref in refs
        ):
            raise PreprocessorError("english_mcp_grounding_invalid")
        if len(refs) != len(set(refs)):
            raise PreprocessorError("english_mcp_grounding_invalid")
        cited_collections = {
            str(rows_by_ref[ref]["collection"])
            for ref in refs
        }
        if "task_artifact" not in cited_collections or not (
            cited_collections - {"task_context", "task_artifact"}
        ):
            raise PreprocessorError("english_mcp_grounding_missing")


def normalize_english_critical_review_exact_duplicates(
    review: Mapping[str, Any],
) -> tuple[dict[str, Any], list[dict[str, str]]]:
    """Remove only byte-semantically exact duplicate review rows.

    Reusing an identifier for a different row remains a hard validation error.
    This narrow normalization covers the production incident where the final
    finding was emitted twice without weakening correction ownership.
    """

    normalized = copy.deepcopy(dict(review))
    warnings: list[dict[str, str]] = []
    for collection, identifier, warning_code in (
        ("findings", "correction_id", "english_exact_duplicate_finding_removed"),
        (
            "correction_resolutions",
            "finding_id",
            "english_exact_duplicate_resolution_removed",
        ),
    ):
        rows = normalized.get(collection)
        if not isinstance(rows, list):
            continue
        accepted: list[Any] = []
        first_by_id: dict[str, Any] = {}
        for index, row in enumerate(rows):
            row_id = (
                str(row.get(identifier) or "")
                if isinstance(row, Mapping)
                else ""
            )
            first = first_by_id.get(row_id) if row_id else None
            if first is not None and first == row:
                warnings.append(
                    {
                        "code": warning_code,
                        "json_path": f"$.{collection}[{index}]",
                        "message": "exact duplicate removed deterministically",
                    }
                )
                continue
            if row_id and first is None:
                first_by_id[row_id] = copy.deepcopy(row)
            accepted.append(row)
        normalized[collection] = accepted
    return normalized, warnings


def validate_english_critical_review(
    review: Mapping[str, Any], draft: Mapping[str, Any]
) -> None:
    if (
        set(review)
        != {
            "schema_version", "verdict", "draft_analysis_sha256",
            "findings", "correction_resolutions", "revised_items",
        }
        or review.get("schema_version")
        != "study-intake-english-critical-review-v1"
        or review.get("verdict") not in {"confirmed", "revised", "reject"}
        or review.get("draft_analysis_sha256") != sha256_value(draft)
        or not isinstance(review.get("findings"), list)
        or not isinstance(review.get("correction_resolutions"), list)
        or not isinstance(review.get("revised_items"), list)
    ):
        raise PreprocessorError("english_critical_review_invalid")
    correction_ids: set[str] = set()
    correction_path_owners: dict[str, str] = {}
    for finding in review["findings"]:
        if (
            not isinstance(finding, Mapping)
            or set(finding)
            != {
                "correction_id", "code", "severity", "item_id", "message",
                "affected_json_paths",
            }
            or finding.get("severity")
            not in {"info", "warning", "blocking"}
            or not isinstance(finding.get("correction_id"), str)
            or not str(finding.get("correction_id")).strip()
            or finding["correction_id"] in correction_ids
            or not isinstance(finding.get("code"), str)
            or not isinstance(finding.get("message"), str)
            or not isinstance(finding.get("affected_json_paths"), list)
            or len(finding["affected_json_paths"])
            != len(
                {
                    path
                    for path in finding["affected_json_paths"]
                    if isinstance(path, str)
                }
            )
            or any(
                not isinstance(path, str) or not path.startswith("$")
                for path in finding["affected_json_paths"]
            )
            or not (
                finding.get("item_id") is None
                or isinstance(finding.get("item_id"), str)
            )
        ):
            raise PreprocessorError("english_critical_review_invalid")
        correction_id = str(finding["correction_id"])
        for path in finding["affected_json_paths"]:
            owner = correction_path_owners.get(path)
            if owner is not None and owner != correction_id:
                raise PreprocessorError(
                    "english_correction_path_ownership_invalid"
                )
            correction_path_owners[path] = correction_id
        correction_ids.add(correction_id)
    findings_by_id = {
        str(finding["correction_id"]): finding
        for finding in review["findings"]
    }
    resolution_ids = {
        str(resolution.get("finding_id") or "")
        for resolution in review["correction_resolutions"]
    }
    required_ids = {
        correction_id
        for correction_id, finding in findings_by_id.items()
        if finding.get("severity") == "blocking"
    }
    # Blocking findings must all be resolved.  A reviewer may also attach a
    # concrete delta to an informational or warning finding; validate those
    # supplied resolutions instead of treating them as unknown extras.
    normalized_findings = [
        {
            "finding_id": correction_id,
            "severity": "blocking",
        }
        for correction_id in sorted(required_ids | resolution_ids)
        if correction_id in findings_by_id
    ]
    try:
        validate_correction_resolutions(
            normalized_findings, review["correction_resolutions"]
        )
    except SemanticContractError as exc:
        raise PreprocessorError("english_required_correction_unresolved") from exc
    finding_paths = {
        str(finding["correction_id"]): list(finding["affected_json_paths"])
        for finding in review["findings"]
    }
    for resolution in review["correction_resolutions"]:
        finding_id = str(resolution.get("finding_id") or "")
        paths = list(resolution.get("affected_json_paths") or [])
        if (
            paths != finding_paths.get(finding_id)
            or len(paths)
            != len({path for path in paths if isinstance(path, str)})
            or any(
                path != "$.items" and not path.startswith("$.items[")
                for path in paths
            )
        ):
            raise PreprocessorError("english_correction_target_invalid")
        if (
            finding_id in required_ids
            and resolution.get("resolution") != "applied"
        ):
            raise PreprocessorError(
                "english_required_correction_not_applied"
            )


def validate_english_applied_corrections(review: Mapping[str, Any]) -> None:
    """Validate review deltas against the model-owned semantic replacement view."""

    semantic_replacement = {
        "items": copy.deepcopy(list(review.get("revised_items") or []))
    }
    try:
        validate_applied_correction_targets(
            semantic_replacement,
            review.get("correction_resolutions") or [],
        )
    except SemanticContractError as exc:
        raise PreprocessorError(
            "english_required_correction_not_applied",
            diagnostic={"semantic_error_code": str(exc)},
        ) from exc


def materialize_english_correction_deltas(
    review: Mapping[str, Any], draft: Mapping[str, Any]
) -> dict[str, Any]:
    """Bind English correction intent to exact model-owned semantic values.

    The raw model-stage object remains immutable. For the effective critical
    review, the host derives each applied delta from the already-validated
    finding paths, the frozen semantic draft, and ``revised_items``. This
    keeps a lossy or partial model-authored delta from masking a real revision
    while still failing closed when a blocking correction is a no-op.
    """

    effective = copy.deepcopy(dict(review))
    findings = effective.get("findings")
    resolutions_value = effective.get("correction_resolutions")
    if isinstance(findings, list) and isinstance(resolutions_value, list):
        known_ids = {
            str(finding.get("correction_id") or "")
            for finding in findings
            if isinstance(finding, Mapping)
            and isinstance(finding.get("correction_id"), str)
            and str(finding.get("correction_id") or "")
        }
        owners_by_paths: dict[tuple[str, ...], list[str]] = {}
        for finding in findings:
            if not isinstance(finding, Mapping):
                continue
            correction_id = str(finding.get("correction_id") or "")
            paths = finding.get("affected_json_paths")
            if (
                not correction_id
                or not isinstance(paths, list)
                or not paths
                or any(not isinstance(path, str) for path in paths)
                or len(paths) != len(set(paths))
            ):
                continue
            owners_by_paths.setdefault(tuple(paths), []).append(correction_id)
        normalized_resolutions: list[Any] = []
        remapped_ids: set[str] = set()
        for raw_resolution in resolutions_value:
            resolution = copy.deepcopy(raw_resolution)
            if isinstance(resolution, dict):
                finding_id = str(resolution.get("finding_id") or "")
                paths = resolution.get("affected_json_paths")
                owners = (
                    owners_by_paths.get(tuple(paths), [])
                    if isinstance(paths, list)
                    and paths
                    and all(isinstance(path, str) for path in paths)
                    else []
                )
                if (
                    finding_id not in known_ids
                    and len(owners) == 1
                    and owners[0] not in remapped_ids
                ):
                    resolution["finding_id"] = owners[0]
                    remapped_ids.add(owners[0])
            normalized_resolutions.append(resolution)
        effective["correction_resolutions"] = normalized_resolutions
    semantic_replacement = {
        "items": copy.deepcopy(list(effective.get("revised_items") or []))
    }
    resolutions = copy.deepcopy(
        list(effective.get("correction_resolutions") or [])
    )
    resolved_ids = {
        str(row.get("finding_id") or "")
        for row in resolutions
        if isinstance(row, Mapping)
    }
    findings = effective.get("findings")
    path_owners: dict[str, str] = {}
    if isinstance(findings, list):
        for finding in findings:
            if not isinstance(finding, Mapping):
                continue
            finding_id = str(finding.get("correction_id") or "")
            paths = finding.get("affected_json_paths")
            if not finding_id or not isinstance(paths, list):
                continue
            for path in paths:
                if isinstance(path, str):
                    path_owners.setdefault(path, finding_id)
        for finding in findings:
            if (
                not isinstance(finding, Mapping)
                or finding.get("severity") != "blocking"
            ):
                continue
            finding_id = str(finding.get("correction_id") or "")
            paths = finding.get("affected_json_paths")
            if (
                not finding_id
                or finding_id in resolved_ids
                or not isinstance(paths, list)
                or not paths
                or any(not isinstance(path, str) for path in paths)
                or len(paths) != len(set(paths))
                or any(
                    path_owners.get(path) != finding_id
                    or (
                        path != "$.items"
                        and not path.startswith("$.items[")
                    )
                    for path in paths
                )
            ):
                continue
            try:
                changed = True
                for path in paths:
                    after = _resolve_correction_json_path(
                        semantic_replacement, path
                    )
                    try:
                        before = _resolve_correction_json_path(draft, path)
                    except PreprocessorError as exc:
                        if exc.code != "critical_review_correction_target_missing":
                            raise
                        before = {
                            **ENGLISH_CORRECTION_PATH_ABSENT,
                            "path": path,
                        }
                    if before == after:
                        changed = False
                        break
            except PreprocessorError:
                changed = False
            if not changed:
                continue
            resolutions.append(
                {
                    "finding_id": finding_id,
                    "resolution": "applied",
                    "affected_json_paths": copy.deepcopy(paths),
                    "before": encode_correction_delta(None),
                    "after": encode_correction_delta(None),
                }
            )
            resolved_ids.add(finding_id)
    effective["correction_resolutions"] = _materialize_correction_deltas(
        resolutions,
        draft_analysis=copy.deepcopy(dict(draft)),
        revised_analysis=semantic_replacement,
        invalid_code="english_required_correction_not_applied",
        no_op_code="english_required_correction_not_applied",
        allow_missing_before=True,
    )
    return effective


class PreprocessorError(RuntimeError):
    """Expected fail-closed core error."""

    def __init__(
        self,
        code: str,
        message: str | None = None,
        *,
        diagnostic: Mapping[str, Any] | None = None,
    ) -> None:
        super().__init__(message or code)
        self.code = code
        self.diagnostic = dict(diagnostic or {})


class _McpReviewPolicyViolation(PreprocessorError):
    """One fully validated MCP transcript that is reviewable, not adoptable."""

    def __init__(
        self,
        code: str,
        *,
        calls: Sequence[Mapping[str, Any]],
        transcript_sha256: str,
        transcript_ref: str,
        duplicate_result_projection_sha256: str,
    ) -> None:
        super().__init__(code)
        self.calls = tuple(copy.deepcopy(dict(call)) for call in calls)
        self.transcript_sha256 = transcript_sha256
        self.transcript_ref = transcript_ref
        self.duplicate_result_projection_sha256 = (
            duplicate_result_projection_sha256
        )


def canonical_bytes(value: Any) -> bytes:
    return json.dumps(
        value, ensure_ascii=False, sort_keys=True, separators=(",", ":")
    ).encode("utf-8")


def json_file_bytes(value: Mapping[str, Any]) -> bytes:
    return json.dumps(
        value, ensure_ascii=False, indent=2, sort_keys=True
    ).encode("utf-8") + b"\n"


def sha256_text(value: str) -> str:
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


def sha256_value(value: Any) -> str:
    return hashlib.sha256(canonical_bytes(value)).hexdigest()


def _plugin_owned_sha256_value(value: Any) -> str:
    """Hash plugin-owned canonical JSON values using the plugin LF contract."""

    return hashlib.sha256(canonical_bytes(value) + b"\n").hexdigest()


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _cs408_status_script_sha256(raw_path: Any) -> str:
    """Hash the configured 408 projector without following a symlink."""

    if not isinstance(raw_path, str) or not raw_path:
        raise PreprocessorError("cs408_status_script_invalid")
    path = Path(raw_path).expanduser()
    if not path.is_absolute():
        raise PreprocessorError("cs408_status_script_invalid")
    try:
        before = path.lstat()
        if stat.S_ISLNK(before.st_mode) or not stat.S_ISREG(before.st_mode):
            raise PreprocessorError("cs408_status_script_invalid")
        if not os.access(path, os.R_OK):
            raise PreprocessorError("cs408_status_script_invalid")
        raw = path.read_bytes()
        after = path.lstat()
    except PreprocessorError:
        raise
    except OSError as exc:
        raise PreprocessorError("cs408_status_script_invalid") from exc
    if (
        stat.S_ISLNK(after.st_mode)
        or not stat.S_ISREG(after.st_mode)
        or (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns)
        != (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns)
        or len(raw) != before.st_size
    ):
        raise PreprocessorError("cs408_status_script_invalid")
    return hashlib.sha256(raw).hexdigest()


def model_mcp_item_ref(
    *,
    subject: str,
    generation: str,
    collection: str,
    stable_id: str,
    source_hash: str,
) -> str:
    digest = sha256_value({
        "collection": collection,
        "generation": generation,
        "source_hash": source_hash,
        "stable_id": stable_id,
    })
    return f"mcp-item:{subject}:{digest}"


def utc_now() -> str:
    return dt.datetime.now(dt.timezone.utc).isoformat().replace("+00:00", "Z")


def parse_time(value: Any) -> dt.datetime | None:
    if not isinstance(value, str) or not value:
        return None
    text = value[:-1] + "+00:00" if value.endswith("Z") else value
    try:
        parsed = dt.datetime.fromisoformat(text)
    except ValueError:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=dt.timezone.utc)
    return parsed.astimezone(dt.timezone.utc)


def current_date(timezone: str) -> str:
    return dt.datetime.now(ZoneInfo(timezone)).date().isoformat()


def dashboard_archive_path(projection_path: Path, study_date: str) -> Path:
    validate_date(study_date)
    return projection_path.parent / "dashboard-projections" / f"{study_date}.json"


def validate_date(value: str) -> str:
    if not DATE_RE.fullmatch(value):
        raise PreprocessorError("invalid_study_date")
    try:
        dt.date.fromisoformat(value)
    except ValueError as exc:
        raise PreprocessorError("invalid_study_date") from exc
    return value


def validate_subject(value: str) -> str:
    if value not in SUBJECTS:
        raise PreprocessorError("invalid_subject")
    return value


def validate_safe_id(value: str, field: str = "id") -> str:
    if not isinstance(value, str) or not SAFE_ID_RE.fullmatch(value):
        raise PreprocessorError(f"invalid_{field}")
    return value


def safe_component(value: str) -> str:
    if SAFE_ID_RE.fullmatch(value):
        return value
    return hashlib.sha256(value.encode("utf-8")).hexdigest()[:32]


def canonical_subject_package_path(
    runtime_root: Path,
    *,
    subject: str,
    study_date: str,
    capture_id: str,
    input_fingerprint: str,
    package_sha256: str,
) -> Path:
    """Return the sole canonical Worker package location for one subject."""

    validate_subject(subject)
    validate_date(study_date)
    _validate_hash(input_fingerprint, "input_fingerprint")
    _validate_hash(package_sha256, "package_sha256")
    if not isinstance(capture_id, str) or not capture_id or len(capture_id) > 256:
        raise PreprocessorError("subject_package_identity_invalid")
    root = Path(runtime_root).resolve()
    if subject == "english":
        return (
            root
            / "packages"
            / subject
            / study_date
            / safe_component(capture_id)
            / f"{input_fingerprint}.json"
        )
    return root / "packages" / "objects" / f"{package_sha256}.json"


def load_json(path: Path) -> dict[str, Any]:
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except FileNotFoundError as exc:
        raise PreprocessorError("json_missing") from exc
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise PreprocessorError("json_invalid") from exc
    if not isinstance(value, dict):
        raise PreprocessorError("json_not_object")
    return value


class _DispatchFencedWriteGuard:
    """Exclude lease takeover while one production child publishes a file.

    The legacy monolith does not set these variables and therefore keeps its
    existing behaviour.  The concurrent production child sets the complete
    binding.  Every atomic core write then shares the dispatcher's lock and
    verifies the exact owner/fence before it can create or replace anything.
    No lock is held while a model request is running.
    """

    _ENV_NAMES = (
        "STUDY_PREPROCESS_RUNTIME_ROOT",
        "STUDY_PREPROCESS_UNIT_SHA256",
        "STUDY_PREPROCESS_LEASE_FENCE",
        "STUDY_PREPROCESS_LEASE_OWNER_ID",
    )

    def __init__(self) -> None:
        self._handle: Any = None

    def __enter__(self) -> "_DispatchFencedWriteGuard":
        raw = {name: os.environ.get(name) for name in self._ENV_NAMES}
        configured = [value is not None for value in raw.values()]
        if not any(configured):
            return self
        if not all(configured):
            raise PreprocessorError(
                "dispatch_fence_environment_incomplete"
            )
        runtime_text = str(raw["STUDY_PREPROCESS_RUNTIME_ROOT"])
        unit_sha256 = str(raw["STUDY_PREPROCESS_UNIT_SHA256"])
        owner_id = str(raw["STUDY_PREPROCESS_LEASE_OWNER_ID"])
        fence_text = str(raw["STUDY_PREPROCESS_LEASE_FENCE"])
        try:
            fence = int(fence_text)
        except ValueError as exc:
            raise PreprocessorError("dispatch_fence_environment_invalid") from exc
        runtime_root = Path(runtime_text)
        if (
            not runtime_root.is_absolute()
            or not SHA256_RE.fullmatch(unit_sha256)
            or not owner_id
            or len(owner_id) > 256
            or fence < 1
            or str(fence) != fence_text
        ):
            raise PreprocessorError("dispatch_fence_environment_invalid")
        state_root = runtime_root.resolve() / "dispatch" / "state"
        lock_path = state_root / "dispatch.lock"
        lease_path = state_root / "leases" / f"{unit_sha256}.json"
        lock_path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
        self._handle = lock_path.open("a+b")
        fcntl.flock(self._handle.fileno(), fcntl.LOCK_EX)
        try:
            lease = json.loads(lease_path.read_text(encoding="utf-8"))
        except (FileNotFoundError, OSError, UnicodeError, json.JSONDecodeError) as exc:
            self.__exit__()
            raise PreprocessorError("stale_lease_fence") from exc
        if (
            not isinstance(lease, Mapping)
            or lease.get("schema_version")
            != "study-intake-dispatch-lease-v1"
            or lease.get("unit_sha256") != unit_sha256
            or lease.get("owner_id") != owner_id
            or lease.get("fence") != fence
            or lease.get("status") != "claimed"
        ):
            self.__exit__()
            raise PreprocessorError("stale_lease_fence")
        return self

    def __exit__(self, *_args: object) -> None:
        if self._handle is not None:
            fcntl.flock(self._handle.fileno(), fcntl.LOCK_UN)
            self._handle.close()
            self._handle = None


def atomic_write_json(path: Path, value: Mapping[str, Any]) -> None:
    with _DispatchFencedWriteGuard():
        path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
        os.chmod(path.parent, 0o700)
        payload = json_file_bytes(value)
        fd, temp_name = tempfile.mkstemp(prefix=f".{path.name}.", dir=path.parent)
        temp_path = Path(temp_name)
        try:
            os.fchmod(fd, 0o600)
            with os.fdopen(fd, "wb") as handle:
                handle.write(payload)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temp_path, path)
            directory_fd = os.open(path.parent, os.O_RDONLY)
            try:
                os.fsync(directory_fd)
            finally:
                os.close(directory_fd)
        finally:
            try:
                temp_path.unlink()
            except FileNotFoundError:
                pass


def atomic_publish_json_no_clobber(
    path: Path, value: Mapping[str, Any]
) -> None:
    """Publish canonical JSON exactly once without replacing an existing path."""

    with _DispatchFencedWriteGuard():
        path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
        os.chmod(path.parent, 0o700)
        payload = json_file_bytes(value)
        fd, temp_name = tempfile.mkstemp(prefix=f".{path.name}.", dir=path.parent)
        temp_path = Path(temp_name)
        try:
            os.fchmod(fd, 0o600)
            with os.fdopen(fd, "wb") as handle:
                handle.write(payload)
                handle.flush()
                os.fsync(handle.fileno())
            try:
                os.link(temp_path, path)
            except FileExistsError:
                try:
                    existing = path.read_bytes()
                except OSError as exc:
                    raise PreprocessorError("json_no_clobber_conflict") from exc
                if existing != payload:
                    raise PreprocessorError("json_no_clobber_conflict")
            directory_fd = os.open(path.parent, os.O_RDONLY)
            try:
                os.fsync(directory_fd)
            finally:
                os.close(directory_fd)
        finally:
            try:
                temp_path.unlink()
            except FileNotFoundError:
                pass


def atomic_publish_bytes_no_clobber(path: Path, payload: bytes) -> None:
    """Publish exact immutable bytes once, preserving byte-level authority."""

    with _DispatchFencedWriteGuard():
        path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
        os.chmod(path.parent, 0o700)
        descriptor, raw_temp = tempfile.mkstemp(
            prefix=f".{path.name}.", dir=path.parent
        )
        temp = Path(raw_temp)
        try:
            os.fchmod(descriptor, 0o600)
            with os.fdopen(descriptor, "wb") as handle:
                handle.write(payload)
                handle.flush()
                os.fsync(handle.fileno())
            try:
                os.link(temp, path)
            except FileExistsError:
                if path.read_bytes() != payload:
                    raise PreprocessorError("bytes_no_clobber_conflict")
        finally:
            try:
                temp.unlink()
            except FileNotFoundError:
                pass


def atomic_write_text(path: Path, value: str) -> None:
    with _DispatchFencedWriteGuard():
        path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
        os.chmod(path.parent, 0o700)
        payload = value.encode("utf-8")
        fd, temp_name = tempfile.mkstemp(prefix=f".{path.name}.", dir=path.parent)
        temp_path = Path(temp_name)
        try:
            os.fchmod(fd, 0o600)
            with os.fdopen(fd, "wb") as handle:
                handle.write(payload)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temp_path, path)
            directory_fd = os.open(path.parent, os.O_RDONLY)
            try:
                os.fsync(directory_fd)
            finally:
                os.close(directory_fd)
        finally:
            try:
                temp_path.unlink()
            except FileNotFoundError:
                pass


def atomic_restore_json_if_current(
    path: Path,
    *,
    expected_current: Mapping[str, Any],
    replacement: Mapping[str, Any] | None,
) -> bool:
    """Rollback one JSON path only for the still-current lease generation.

    The dispatch fence is checked while the dispatch lock is held.  The exact
    bytes written by the failed publication must also still be present, so a
    late exception cannot restore over, or unlink, a newer publication.
    """

    with _DispatchFencedWriteGuard():
        expected_payload = json_file_bytes(expected_current)
        try:
            current_payload = path.read_bytes()
        except FileNotFoundError:
            return False
        except OSError as exc:
            raise PreprocessorError("json_rollback_read_failed") from exc
        if current_payload != expected_payload:
            return False
        if replacement is None:
            try:
                path.unlink()
            except FileNotFoundError:
                return False
        else:
            payload = json_file_bytes(replacement)
            fd, temp_name = tempfile.mkstemp(
                prefix=f".{path.name}.", dir=path.parent
            )
            temp_path = Path(temp_name)
            try:
                os.fchmod(fd, 0o600)
                with os.fdopen(fd, "wb") as handle:
                    handle.write(payload)
                    handle.flush()
                    os.fsync(handle.fileno())
                os.replace(temp_path, path)
            finally:
                try:
                    temp_path.unlink()
                except FileNotFoundError:
                    pass
        directory_fd = os.open(path.parent, os.O_RDONLY)
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
        return True


class FileLock:
    def __init__(self, path: Path, *, blocking: bool = False) -> None:
        self.path = path
        self.blocking = blocking
        self._handle: Any = None

    def __enter__(self) -> "FileLock":
        self.path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
        os.chmod(self.path.parent, 0o700)
        self._handle = self.path.open("a+", encoding="utf-8")
        os.chmod(self.path, 0o600)
        flags = fcntl.LOCK_EX
        if not self.blocking:
            flags |= fcntl.LOCK_NB
        try:
            fcntl.flock(self._handle.fileno(), flags)
        except BlockingIOError as exc:
            self._handle.close()
            self._handle = None
            raise PreprocessorError("worker_already_running") from exc
        return self

    def __exit__(self, *_: object) -> None:
        if self._handle is not None:
            fcntl.flock(self._handle.fileno(), fcntl.LOCK_UN)
            self._handle.close()
            self._handle = None


def configure_logger(path: Path) -> logging.Logger:
    logger = logging.getLogger("study-intake-preprocessor")
    if logger.handlers:
        return logger
    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    os.chmod(path.parent, 0o700)
    handler = logging.handlers.RotatingFileHandler(
        path, maxBytes=5 * 1024 * 1024, backupCount=3, encoding="utf-8"
    )
    handler.setFormatter(logging.Formatter("%(asctime)s %(levelname)s %(message)s"))
    logger.addHandler(handler)
    os.chmod(path, 0o600)
    logger.setLevel(logging.INFO)
    logger.propagate = False
    return logger


def _profile_soft_runtime_warning_seconds(
    profile: Mapping[str, Any], *, default: int
) -> int:
    """Read the successor soft wall-clock warning with v1 compatibility.

    ``stage_timeout_seconds`` is accepted only as an old configuration alias.
    Neither value is passed to ``Popen.communicate`` or used as proof of a
    stalled Provider.
    """

    raw = profile.get(
        "soft_runtime_warning_seconds",
        profile.get("stage_timeout_seconds", default),
    )
    if isinstance(raw, bool) or not isinstance(raw, int) or raw < 60:
        raise PreprocessorError("config_soft_runtime_warning_seconds_invalid")
    return raw


def _validate_profile_stall_config(profile: Mapping[str, Any]) -> None:
    for key, default, lower in (
        ("stall_timeout_seconds", 1800, 60),
        ("stall_probe_interval_seconds", 60, 1),
        ("stall_probe_required_consecutive_failures", 2, 2),
    ):
        raw = profile.get(key, default)
        if (
            isinstance(raw, bool)
            or not isinstance(raw, int)
            or raw < lower
            or (key == "stall_probe_required_consecutive_failures" and raw != 2)
        ):
            raise PreprocessorError(f"config_{key}_invalid")


def _materialize_legacy_fixture_v2_config(
    config: dict[str, Any], *, config_path: Path
) -> dict[str, Any]:
    """Upgrade old isolated unit fixtures without weakening release config.

    The compatibility path is available only under the explicit zero-model
    fixture environment and only when none of the V2 execution keys is
    present.  Any partially supplied or production configuration remains
    subject to the strict validators below.
    """

    v2_keys = {
        "execution_mode",
        "live_execution_gate",
        "fixture_execution",
        "branch_scheduler",
        "models",
    }
    if (
        os.environ.get("STUDY_INTAKE_FIXTURE_EXECUTION") != "1"
        or any(key in config for key in v2_keys)
    ):
        return config
    source_root = Path(__file__).resolve().parents[1]
    runtime_root = Path(str(config.get("runtime_root") or config_path.parent))
    if not runtime_root.is_absolute():
        runtime_root = (config_path.parent / runtime_root).resolve()
    plugin_root = source_root / "plugin/kaoyan-study-intake"
    config.update(
        {
            "execution_mode": "fixture",
            "live_execution_gate": {
                "enabled": True,
                "default_locked": True,
                "authorization_required": True,
                "authorization_state_path": str(
                    runtime_root
                    / "dispatch/manual-live-authorization-v1/state.json"
                ),
            },
            "fixture_execution": {
                "allowed_executable_roots": sorted(
                    {
                        str(source_root / "tests/fixtures"),
                        str(runtime_root),
                        str(runtime_root.parent),
                    }
                )
            },
            "branch_scheduler": {
                "logical_branch_limit": None,
                "physical_concurrency_mode": "dynamic",
                "configured_maximum_active_branches": 8,
                "overflow_policy": "queue_in_waves",
                "drop_policy": "never",
                "fairness_policy": "round_robin_tasks",
                "stall_timeout_seconds": 120,
            },
            "models": {
                "orchestrator": {
                    "model": "gpt-5.6-terra",
                    "reasoning_effort": "ultra",
                    "agents_enabled": True,
                    "fresh_context": True,
                    "sandbox_mode": "workspace-write",
                    "agent_config_path": str(
                        plugin_root / "agents/terra-orchestrator.toml"
                    ),
                    "tool_policy_path": str(
                        plugin_root
                        / "agents/terra-orchestrator-tool-policy.json"
                    ),
                },
                "reader": {
                    "model": "gpt-5.6-luna",
                    "reasoning_effort": "max",
                    "agents_enabled": False,
                    "fresh_context": True,
                    "sandbox_mode": "read-only",
                    "agent_config_path": str(
                        plugin_root / "agents/luna-reader.toml"
                    ),
                    "tool_policy_path": str(
                        plugin_root / "agents/luna-reader-tool-policy.json"
                    ),
                },
                "critical_reviewer": {
                    "model": "gpt-5.6-terra",
                    "reasoning_effort": "ultra",
                    "agents_enabled": False,
                    "fresh_context": True,
                    "sandbox_mode": "read-only",
                    "agent_config_path": str(
                        plugin_root / "agents/terra-critical-reviewer.toml"
                    ),
                    "tool_policy_path": str(
                        plugin_root
                        / "agents/terra-critical-reviewer-tool-policy.json"
                    ),
                },
            },
        }
    )
    return config


def load_config(path: Path) -> dict[str, Any]:
    config = _materialize_legacy_fixture_v2_config(
        load_json(path), config_path=path
    )
    if config.get("schema_version") != CONFIG_SCHEMA:
        raise PreprocessorError("config_schema_mismatch")
    for section in ("worker", "dispatch", "model", "dashboard", "adapters"):
        if not isinstance(config.get(section), dict):
            raise PreprocessorError(f"config_missing_{section}")
    dispatch = config["dispatch"]
    if (
        dispatch.get("authority_required") is not True
        or dispatch.get("heartbeat_interval_seconds") != 15
        or dispatch.get("lease_ttl_seconds") != 120
        or dispatch.get("infrastructure_recovery_attempts") != 1
    ):
        raise PreprocessorError("config_dispatch_contract_invalid")
    if config["model"].get("model") != "gpt-5.6-luna":
        raise PreprocessorError("config_model_must_be_luna")
    if config["model"].get("reasoning_effort") != "max":
        raise PreprocessorError("config_reasoning_must_be_max")
    if "service_tier" in config["model"]:
        raise PreprocessorError("config_service_tier_must_be_absent")
    if config["model"].get("max_images") != 8:
        raise PreprocessorError("config_model_max_images_must_be_8")
    execution_mode = config.get("execution_mode")
    if execution_mode not in {"fixture", "offline", "live_authorized"}:
        raise PreprocessorError("config_execution_mode_invalid")
    declared_execution_mode = os.environ.get("STUDY_INTAKE_EXECUTION_MODE")
    if (
        declared_execution_mode is not None
        and declared_execution_mode != execution_mode
    ):
        raise PreprocessorError("config_execution_mode_environment_mismatch")
    live_gate = config.get("live_execution_gate")
    if (
        not isinstance(live_gate, Mapping)
        or set(live_gate) != {
            "enabled",
            "default_locked",
            "authorization_required",
            "authorization_state_path",
        }
        or live_gate.get("enabled") is not True
        or live_gate.get("default_locked") is not True
        or live_gate.get("authorization_required") is not True
        or not isinstance(live_gate.get("authorization_state_path"), str)
        or not Path(str(live_gate["authorization_state_path"])).is_absolute()
    ):
        raise PreprocessorError("config_live_execution_gate_invalid")
    fixture_execution = config.get("fixture_execution")
    fixture_roots = (
        fixture_execution.get("allowed_executable_roots")
        if isinstance(fixture_execution, Mapping)
        else None
    )
    if (
        not isinstance(fixture_roots, list)
        or not fixture_roots
        or any(
            not isinstance(root, str) or not Path(root).is_absolute()
            for root in fixture_roots
        )
    ):
        raise PreprocessorError("config_fixture_execution_invalid")
    scheduler = config.get("branch_scheduler")
    if (
        not isinstance(scheduler, Mapping)
        or set(scheduler) != {
            "logical_branch_limit",
            "physical_concurrency_mode",
            "configured_maximum_active_branches",
            "overflow_policy",
            "drop_policy",
            "fairness_policy",
            "stall_timeout_seconds",
        }
        or scheduler.get("logical_branch_limit") is not None
        or scheduler.get("physical_concurrency_mode") != "dynamic"
        or isinstance(scheduler.get("configured_maximum_active_branches"), bool)
        or not isinstance(scheduler.get("configured_maximum_active_branches"), int)
        or not 1 <= int(scheduler["configured_maximum_active_branches"]) <= 128
        or scheduler.get("overflow_policy") != "queue_in_waves"
        or scheduler.get("drop_policy") != "never"
        or scheduler.get("fairness_policy") != "round_robin_tasks"
        or isinstance(scheduler.get("stall_timeout_seconds"), bool)
        or not isinstance(scheduler.get("stall_timeout_seconds"), int)
        or not 10 <= int(scheduler["stall_timeout_seconds"]) <= 3600
    ):
        raise PreprocessorError("config_branch_scheduler_invalid")
    try:
        from model_role_contract import (
            ModelRoleContractError,
            model_contract_from_config,
        )

        config["multi_agent_model_contract"] = model_contract_from_config(config)
    except ModelRoleContractError as exc:
        raise PreprocessorError(exc.code) from exc
    processing_plugin = config.get("processing_plugin")
    if processing_plugin is not None:
        if (
            not isinstance(processing_plugin, dict)
            or processing_plugin.get("enabled") is not True
            or processing_plugin.get("profile") != "background"
            or processing_plugin.get("timeout_seconds") != 30
        ):
            raise PreprocessorError("config_processing_plugin_invalid")
        for key in (
            "root",
            "component_lock_path",
            "mcp_client_python",
            "mcp_project_root",
            "authority_key_path",
        ):
            raw = processing_plugin.get(key)
            if not isinstance(raw, str) or not Path(raw).is_absolute():
                raise PreprocessorError(f"config_processing_plugin_{key}_invalid")
        plugin_root = Path(processing_plugin["root"]).resolve()
        lock_path = Path(processing_plugin["component_lock_path"]).resolve()
        if (
            lock_path.parent != plugin_root
            or not (plugin_root / "plugin.json").is_file()
            or not (plugin_root / "mcp.json").is_file()
            or not lock_path.is_file()
        ):
            raise PreprocessorError("config_processing_plugin_binding_missing")
    if not isinstance(config["worker"].get("enabled"), bool):
        raise PreprocessorError("config_worker_enabled_invalid")
    for subject in ("math", "cs408"):
        adapter = config["adapters"].get(subject)
        if not isinstance(adapter, dict) or not isinstance(adapter.get("enabled"), bool):
            raise PreprocessorError(f"config_adapter_{subject}_invalid")
    english_adapter = config["adapters"].get("english")
    if english_adapter is not None and (
        not isinstance(english_adapter, dict)
        or not isinstance(english_adapter.get("enabled"), bool)
    ):
        raise PreprocessorError("config_adapter_english_invalid")
    english_profile = config.get(ENGLISH_PROFILE)
    if english_adapter and english_adapter.get("enabled") is True:
        if not isinstance(english_profile, dict) or english_profile.get("enabled") is not True:
            raise PreprocessorError("config_english_profile_missing")
        required = (
            "analysis_output_schema",
            "critical_review_output_schema",
            "package_output_schema",
            "controlled_contract_path",
            "analysis_prompt_version",
            "critical_review_prompt_version",
            "max_prompt_bytes",
            "max_output_bytes",
        )
        if any(key not in english_profile for key in required):
            raise PreprocessorError("config_english_profile_incomplete")
        for key in (
            "analysis_output_schema",
            "critical_review_output_schema",
            "package_output_schema",
            "controlled_contract_path",
        ):
            schema_path = english_profile.get(key)
            if (
                not isinstance(schema_path, str)
                or not Path(schema_path).is_absolute()
                or not Path(schema_path).is_file()
            ):
                raise PreprocessorError(f"config_english_{key}_invalid")
        _profile_soft_runtime_warning_seconds(english_profile, default=1800)
        _validate_profile_stall_config(english_profile)
        for key in ("max_prompt_bytes", "max_output_bytes"):
            raw = english_profile.get(key)
            if (
                isinstance(raw, bool)
                or not isinstance(raw, int)
                or not 4096 <= raw <= 2 * 1024 * 1024
            ):
                raise PreprocessorError(f"config_english_{key}_invalid")
        english_poll = config["worker"].get("english_poll_interval_seconds")
        if (
            isinstance(english_poll, bool)
            or not isinstance(english_poll, int)
            or not 1 <= english_poll <= 10
        ):
            raise PreprocessorError("config_english_poll_interval_invalid")
    release = config.get("release")
    if release is not None and (
        not isinstance(release, dict)
        or not isinstance(release.get("manifest_path"), str)
        or not Path(str(release["manifest_path"])).is_absolute()
    ):
        raise PreprocessorError("config_release_invalid")
    math_deep = config.get(MATH_V2_PROFILE)
    math_knowledge_snapshot = config.get(MATH_KNOWLEDGE_SNAPSHOT)
    if math_deep is not None:
        if (
            not isinstance(math_deep, dict)
            or not isinstance(math_deep.get("enabled"), bool)
            or math_deep.get("mode") not in {"shadow", "canary", "production"}
            or math_deep.get("canary_percent") not in {10, 25, 50}
        ):
            raise PreprocessorError("config_math_deep_v2_invalid")
        required = (
            "analysis_output_schema",
            "critical_review_output_schema",
            "package_output_schema",
            "analysis_prompt_version",
            "critical_review_prompt_version",
            "shadow_evaluation_start_at",
            "shadow_evaluation_target_count",
            "max_prompt_bytes",
            "max_output_bytes",
            "min_complete_chinese_chars",
            "max_chinese_chars",
            "gs111_cold_replay_max_seconds",
            "three_replay_p95_max_seconds",
        )
        if any(key not in math_deep for key in required):
            raise PreprocessorError("config_math_deep_v2_incomplete")
        evaluation_start = parse_time(math_deep.get("shadow_evaluation_start_at"))
        evaluation_target = math_deep.get("shadow_evaluation_target_count")
        if evaluation_start is None:
            raise PreprocessorError("config_math_shadow_evaluation_start_invalid")
        if (
            isinstance(evaluation_target, bool)
            or not isinstance(evaluation_target, int)
            or evaluation_target != 20
        ):
            raise PreprocessorError("config_math_shadow_evaluation_target_invalid")
        _profile_soft_runtime_warning_seconds(math_deep, default=3600)
        _validate_profile_stall_config(math_deep)
        for key in (
            "analysis_output_schema",
            "critical_review_output_schema",
            "package_output_schema",
        ):
            schema_path = Path(str(math_deep[key])).expanduser().resolve()
            if not schema_path.is_file():
                raise PreprocessorError(f"config_math_{key}_missing")
        for key in ("max_prompt_bytes", "max_output_bytes"):
            raw = math_deep.get(key)
            if isinstance(raw, bool) or not isinstance(raw, int) or not (
                4096 <= raw <= 2 * 1024 * 1024
            ):
                raise PreprocessorError(f"config_math_{key}_invalid")
        minimum = math_deep.get("min_complete_chinese_chars")
        maximum = math_deep.get("max_chinese_chars")
        if (
            isinstance(minimum, bool)
            or not isinstance(minimum, int)
            or isinstance(maximum, bool)
            or not isinstance(maximum, int)
            or not 0 <= minimum <= maximum <= 20_000
        ):
            raise PreprocessorError("config_math_report_depth_invalid")
        for key, expected in (
            ("gs111_cold_replay_max_seconds", 1800),
            ("three_replay_p95_max_seconds", 1200),
        ):
            raw = math_deep.get(key)
            if (
                isinstance(raw, bool)
                or not isinstance(raw, int)
                or raw != expected
            ):
                raise PreprocessorError(f"config_math_{key}_invalid")
        if math_deep.get("enabled") is True:
            if (
                not isinstance(math_knowledge_snapshot, dict)
                or math_knowledge_snapshot.get("enabled") is not True
            ):
                raise PreprocessorError("config_math_knowledge_snapshot_missing")
            sources = math_knowledge_snapshot.get("sources")
            if not isinstance(sources, dict) or set(sources) != {
                "graph", "projection", "taxonomy", "relationship_policy"
            }:
                raise PreprocessorError("config_math_knowledge_sources_invalid")
            for kind, raw in sources.items():
                if (
                    not isinstance(raw, str)
                    or not raw.strip()
                    or Path(raw).is_absolute()
                    or ".." in Path(raw).parts
                ):
                    raise PreprocessorError(
                        f"config_math_knowledge_source_{kind}_invalid"
                    )
            integer_limits = {
                "max_source_bytes": (4096, 32 * 1024 * 1024),
                "max_distribution_terms": (8, 128),
                "max_local_neighbors": (1, 16),
                "max_relationship_candidates": (1, 5),
                "max_snapshot_bytes": (4096, 262144),
            }
            for key, (lower, upper) in integer_limits.items():
                raw = math_knowledge_snapshot.get(key)
                if (
                    isinstance(raw, bool)
                    or not isinstance(raw, int)
                    or not lower <= raw <= upper
                ):
                    raise PreprocessorError(f"config_math_{key}_invalid")
            regressions = math_knowledge_snapshot.get("golden_regressions", {})
            if not isinstance(regressions, Mapping) or any(
                not isinstance(source_id, str)
                or not SAFE_ID_RE.fullmatch(source_id)
                or not isinstance(expected_ids, list)
                or len(expected_ids) > 16
                or any(
                    not isinstance(expected_id, str)
                    or not SAFE_ID_RE.fullmatch(expected_id)
                    for expected_id in expected_ids
                )
                for source_id, expected_ids in regressions.items()
            ):
                raise PreprocessorError("config_math_golden_regressions_invalid")
    deep = config.get(CS408_V2_PROFILE)
    private_evidence = config.get("private_evidence")
    knowledge_snapshot = config.get(CS408_KNOWLEDGE_SNAPSHOT)
    if deep is not None:
        if not isinstance(deep, dict) or not isinstance(deep.get("enabled"), bool):
            raise PreprocessorError("config_cs408_deep_v2_invalid")
        required = (
            "analysis_output_schema",
            "critical_review_output_schema",
            "package_output_schema",
            "controlled_contract_path",
            "analysis_prompt_version",
            "critical_review_prompt_version",
            "max_prompt_bytes",
            "max_output_bytes",
        )
        if any(key not in deep for key in required):
            raise PreprocessorError("config_cs408_deep_v2_incomplete")
        for key in (
            "analysis_output_schema",
            "critical_review_output_schema",
            "package_output_schema",
            "controlled_contract_path",
        ):
            schema_path = Path(str(deep[key])).expanduser().resolve()
            if not schema_path.is_file():
                raise PreprocessorError(f"config_{key}_missing")
        _profile_soft_runtime_warning_seconds(deep, default=1800)
        _validate_profile_stall_config(deep)
        if not isinstance(deep.get("max_output_bytes"), int) or not (
            4096 <= int(deep["max_output_bytes"]) <= 2 * 1024 * 1024
        ):
            raise PreprocessorError("config_cs408_max_output_bytes_invalid")
        if not isinstance(deep.get("max_prompt_bytes"), int) or not (
            4096 <= int(deep["max_prompt_bytes"]) <= 2 * 1024 * 1024
        ):
            raise PreprocessorError("config_cs408_max_prompt_bytes_invalid")
        if not isinstance(private_evidence, dict):
            raise PreprocessorError("config_private_evidence_missing")
        if not isinstance(private_evidence.get("current_question_root"), str):
            raise PreprocessorError("config_private_evidence_root_invalid")
        if not isinstance(private_evidence.get("max_bundle_bytes"), int) or not (
            4096 <= int(private_evidence["max_bundle_bytes"]) <= 2 * 1024 * 1024
        ):
            raise PreprocessorError("config_private_evidence_size_invalid")
        if deep.get("enabled") is True:
            if not isinstance(knowledge_snapshot, dict):
                raise PreprocessorError("config_cs408_knowledge_snapshot_missing")
            if knowledge_snapshot.get("enabled") is not True:
                raise PreprocessorError("config_cs408_knowledge_snapshot_disabled")
            sources = knowledge_snapshot.get("sources")
            if not isinstance(sources, dict) or set(sources) != {
                "taxonomy", "nodes", "relations", "review_records",
                "review_unit_mapping",
            }:
                raise PreprocessorError("config_cs408_knowledge_sources_invalid")
            for kind, raw in sources.items():
                if (
                    not isinstance(raw, str)
                    or not raw.strip()
                    or Path(raw).is_absolute()
                    or ".." in Path(raw).parts
                ):
                    raise PreprocessorError(
                        f"config_cs408_knowledge_source_{kind}_invalid"
                    )
            integer_limits = {
                "max_source_bytes": (4096, 32 * 1024 * 1024),
                "max_taxonomy_candidates": (1, 32),
                "max_history_candidates": (1, 32),
                "max_relation_candidates": (1, 64),
                "max_review_timeline_entries": (1, 128),
            }
            for key, (minimum, maximum) in integer_limits.items():
                raw = knowledge_snapshot.get(key)
                if isinstance(raw, bool) or not isinstance(raw, int) or not (
                    minimum <= raw <= maximum
                ):
                    raise PreprocessorError(f"config_cs408_{key}_invalid")
            aliases = knowledge_snapshot.get("controlled_aliases", {})
            if not isinstance(aliases, dict) or any(
                not isinstance(alias, str)
                or not alias.strip()
                or not isinstance(ids, list)
                or len(ids) != len(set(ids))
                or any(
                    not isinstance(knowledge_id, str)
                    or re.fullmatch(r"(?:DS|CO|OS|CN)\d{2}-\d{2}", knowledge_id)
                    is None
                    for knowledge_id in ids
                )
                for alias, ids in aliases.items()
            ):
                raise PreprocessorError("config_cs408_controlled_aliases_invalid")
    for profile_name, error_subject in (
        (MATH_V2_PROFILE, "math"),
        (CS408_V2_PROFILE, "cs408"),
        (ENGLISH_PROFILE, "english"),
    ):
        profile = config.get(profile_name)
        if not isinstance(profile, Mapping):
            continue
        raw_schema_path = profile.get("package_output_schema")
        if not isinstance(raw_schema_path, str):
            raise PreprocessorError(
                f"config_{error_subject}_package_output_schema_invalid"
            )
        schema_path = Path(raw_schema_path).expanduser().resolve()
        if not schema_path.is_file():
            raise PreprocessorError(
                f"config_{error_subject}_package_output_schema_invalid"
            )
        try:
            package_schema = load_json(schema_path)
        except (OSError, ValueError, json.JSONDecodeError) as exc:
            raise PreprocessorError(
                f"config_{error_subject}_package_output_schema_invalid"
            ) from exc
        schema_version_rule = (
            package_schema.get("properties", {}).get("schema_version")
            if isinstance(package_schema, Mapping)
            and isinstance(package_schema.get("properties"), Mapping)
            else None
        )
        if (
            package_schema.get("title")
            != "study-intake-preprocess-package-v3"
            or not isinstance(schema_version_rule, Mapping)
            or schema_version_rule.get("const")
            != "study-intake-preprocess-package-v3"
        ):
            raise PreprocessorError(
                f"config_{error_subject}_package_output_schema_not_v3"
            )
    return config


def _schema_sha256(raw_path: object) -> str:
    path = Path(str(raw_path)).expanduser().resolve()
    if not path.is_file():
        raise PreprocessorError("processing_schema_missing")
    return sha256_file(path)


